//! Tests for decode + framed export with byte-exact EXIF carry-over.
//!
//! Fixtures are generated by `fixtures/gen.py` (Pillow) and committed.
//! The regression guard: after framing, an EXIF reader must still see
//! the original camera values — MakerNotes and internal offsets untouched.

use std::fs;
use std::io::Cursor;

use exif::{Context, In, Reader, Tag, Value};
use framely_core::brand::Brand;
use framely_core::error::FrameError;
use framely_core::jpeg;
use framely_core::layout::FrameLayout;

const TAG_MAKE: Tag = Tag(Context::Tiff, 0x010F);
const TAG_MODEL: Tag = Tag(Context::Tiff, 0x0110);
const TAG_ORIENTATION: Tag = Tag(Context::Tiff, 0x0112);
const TAG_FNUMBER: Tag = Tag(Context::Exif, 0x829D);
const TAG_ISO: Tag = Tag(Context::Exif, 0x8827);
const TAG_FOCAL: Tag = Tag(Context::Exif, 0x920A);
const TAG_LENS: Tag = Tag(Context::Exif, 0xA434);

fn fixture(name: &str) -> Vec<u8> {
    let path = format!("{}/tests/fixtures/{}", env!("CARGO_MANIFEST_DIR"), name);
    fs::read(path).unwrap()
}

fn read_exif(bytes: &[u8]) -> Option<exif::Exif> {
    Reader::new()
        .read_from_container(&mut Cursor::new(bytes))
        .ok()
}

fn field(exif: &exif::Exif, tag: Tag) -> Option<&exif::Field> {
    // kamadak keys fields by (ifd number, tag with context): the Exif
    // sub-IFD entries still report In(0) — the Context inside Tag
    // distinguishes them.
    exif.get_field(tag, In::PRIMARY)
}

fn read_str(bytes: &[u8], tag: Tag) -> Option<String> {
    let exif = read_exif(bytes)?;
    match &field(&exif, tag)?.value {
        Value::Ascii(parts) => Some(String::from_utf8_lossy(parts.first()?).trim().to_string()),
        _ => None,
    }
}

/// Writers reduce rationals (18/10 -> 9/5), so compare by value.
fn read_rational_f64(bytes: &[u8], tag: Tag) -> Option<f64> {
    let exif = read_exif(bytes)?;
    match &field(&exif, tag)?.value {
        Value::Rational(rs) => rs.first().map(|r| r.num as f64 / r.denom as f64),
        _ => None,
    }
}

fn close_f64(a: Option<f64>, b: f64) -> bool {
    a.is_some_and(|v| (v - b).abs() < 1e-6)
}

fn read_ushort(bytes: &[u8], tag: Tag) -> Option<u16> {
    let exif = read_exif(bytes)?;
    match &field(&exif, tag)?.value {
        Value::Short(vs) => vs.first().copied(),
        _ => None,
    }
}

/// ISO may arrive as Short or Long depending on the writer.
fn read_iso(bytes: &[u8]) -> Option<u32> {
    let exif = read_exif(bytes)?;
    match &field(&exif, TAG_ISO)?.value {
        Value::Short(vs) => vs.first().map(|v| *v as u32),
        Value::Long(vs) => vs.first().copied(),
        _ => None,
    }
}

/// The raw Exif APP1 segment payload in a JPEG, exactly as stored (the
/// bytes after `Exif\0\0`), located by scanning segments from SOI.
fn app1_payload(bytes: &[u8]) -> Option<&[u8]> {
    assert_eq!(&bytes[..2], &[0xFF, 0xD8], "input is not a JPEG");
    let mut i = 2;
    while i + 4 <= bytes.len() {
        if bytes[i] != 0xFF {
            return None;
        }
        let marker = bytes[i + 1];
        let len = u16::from_be_bytes([bytes[i + 2], bytes[i + 3]]) as usize;
        if marker == 0xE1 {
            let seg = &bytes[i + 4..(i + 2 + len).min(bytes.len())];
            return seg.strip_prefix(b"Exif\0\0");
        }
        if marker == 0xDA {
            return None; // SOS reached, no APP1 before it
        }
        i += 2 + len;
    }
    None
}

#[test]
fn fixtures_carry_the_values_tests_rely_on() {
    let src = fixture("sony.jpg");
    assert_eq!(read_str(&src, TAG_MAKE).as_deref(), Some("SONY"));
    assert_eq!(read_str(&src, TAG_MODEL).as_deref(), Some("ILCE-7RM4"));
    assert_eq!(read_str(&src, TAG_LENS).as_deref(), Some("FE 35mm F1.8"));
    assert!(close_f64(read_rational_f64(&src, TAG_FNUMBER), 1.8));
    assert!(close_f64(read_rational_f64(&src, TAG_FOCAL), 35.0));
    assert_eq!(read_iso(&src), Some(100));
    assert_eq!(
        read_ushort(&fixture("nikon_rot6.jpg"), TAG_ORIENTATION),
        Some(6)
    );
    assert!(
        app1_payload(&fixture("plain.jpg")).is_none(),
        "plain.jpg must have no EXIF"
    );
}

#[test]
fn framing_carries_the_original_app1_byte_for_byte() {
    let src = fixture("sony.jpg");
    assert!(app1_payload(&src).is_some());
    let out = jpeg::frame_bytes(&src, sony_frame(), 92).unwrap();
    assert_eq!(
        app1_payload(&out),
        app1_payload(&src),
        "APP1 payload must survive the framing round trip unchanged"
    );
}

#[test]
fn exif_fields_survive_a_full_frame_roundtrip() {
    let src = fixture("sony.jpg");
    let out = jpeg::frame_bytes(&src, sony_frame(), 92).unwrap();
    assert_eq!(read_str(&out, TAG_MAKE).as_deref(), Some("SONY"));
    assert_eq!(read_str(&out, TAG_MODEL).as_deref(), Some("ILCE-7RM4"));
    assert_eq!(read_str(&out, TAG_LENS).as_deref(), Some("FE 35mm F1.8"));
    assert!(close_f64(read_rational_f64(&out, TAG_FNUMBER), 1.8));
    assert!(close_f64(read_rational_f64(&out, TAG_FOCAL), 35.0));
    assert_eq!(read_iso(&out), Some(100));
}

#[test]
fn decode_applies_orientation_six() {
    // stored 120x80, orientation 6 -> true 80x120 portrait
    let (photo, _exif) = jpeg::load_bytes(&fixture("nikon_rot6.jpg")).unwrap();
    assert_eq!((photo.width(), photo.height()), (80, 120));
    // uniform color survives the rotation
    let center = photo.get_pixel(40, 60).0;
    assert!((center[0] as i32 - 20).abs() < 6, "got {center:?}");
}

#[test]
fn photo_is_pasted_into_the_framed_output() {
    let src = fixture("sony.jpg");
    let l = sony_frame();
    let out = jpeg::frame_bytes(&src, l.clone(), 92).unwrap();
    let (decoded, _) = jpeg::load_bytes(&src).unwrap();
    let framed = image::load_from_memory(&out).unwrap().into_rgba8();
    assert_eq!(
        (framed.width(), framed.height()),
        (l.canvas_width, l.canvas_height)
    );
    // a pixel inside the photo area matches the decoded source pixel
    // (re-encoded JPEG, so allow a small tolerance)
    let (x, y, _w, _h) = l.photo_rect;
    let a = framed.get_pixel(x + 10, y + 10).0;
    let b = decoded.get_pixel(10, 10).0;
    let close = (0..3).all(|i| (a[i] as i32 - b[i] as i32).abs() <= 6);
    assert!(close, "photo pixel {a:?} != source {b:?}");
    // the canvas must be bigger than the photo: framing happened
    assert!(
        framed.width() > 120 && framed.height() > 80,
        "canvas {}x{} should exceed photo 120x80",
        framed.width(),
        framed.height()
    );
}

#[test]
fn a_picture_without_exif_still_frames_and_exports() {
    let src = fixture("plain.jpg");
    let l = plain_frame();
    let out = jpeg::frame_bytes(&src, l.clone(), 92).unwrap();
    assert!(app1_payload(&out).is_none(), "output must not invent EXIF");
    let img = image::load_from_memory(&out).unwrap().into_rgba8();
    assert_eq!(
        (img.width(), img.height()),
        (l.canvas_width, l.canvas_height)
    );
    // photo paste happened: interior equals source
    let (decoded, _) = jpeg::load_bytes(&src).unwrap();
    let (x, y, _, _) = l.photo_rect;
    let a = img.get_pixel(x + 10, y + 10).0;
    let b = decoded.get_pixel(10, 10).0;
    let close = (0..3).all(|i| (a[i] as i32 - b[i] as i32).abs() <= 6);
    assert!(close, "plain photo {a:?} != source {b:?}");
}

#[test]
fn unsupported_bytes_report_decode_error_not_panic() {
    let err = jpeg::load_bytes(b"not an image").unwrap_err();
    assert!(matches!(
        err,
        FrameError::UnsupportedFormat | FrameError::Decode(_)
    ));
}

// ---- frame helpers matching the fixtures -------------------------------

fn minimal_layout(
    brand: Brand,
    photo_w: u32,
    photo_h: u32,
    parts: Vec<(framely_core::template::Field, String)>,
) -> FrameLayout {
    use framely_core::layout::layout;
    use framely_core::template::{Fields, TemplateId, ThemeConfig};
    layout(
        TemplateId::Minimal,
        photo_w,
        photo_h,
        brand,
        0.5,
        &ThemeConfig::default_for(TemplateId::Minimal),
        &Fields {
            parts,
            custom_line: None,
        },
    )
}

fn sony_frame() -> FrameLayout {
    use framely_core::template::Field;
    minimal_layout(
        Brand::Sony,
        120,
        80,
        vec![
            (Field::Lens, "FE 35mm F1.8".into()),
            (Field::Aperture, "f/1.8".into()),
        ],
    )
}

fn plain_frame() -> FrameLayout {
    minimal_layout(Brand::Unknown, 120, 80, vec![])
}
